export const ENCRYPTED_OBJSTM_PDF_40 = Buffer.from(ENC40_B64, "base64");

/** 20 pages; same encryption/ObjStm structure as the 40-page fixture. */
export const ENCRYPTED_OBJSTM_PDF_20 = Buffer.from(ENC20_B64, "base64");

/** The 40-page fixture after the parse service's normalize — pdf-lib-ready. */
export const ENCRYPTED_OBJSTM_PDF_40_NORMALIZED = Buffer.from(ENC40_NORMALIZED_B64, "base64");

/**
 * 20 pages ("Fixture page N" each), owner-password encrypted (empty user
 * password, R=2) but with NO object streams — so pdf-lib CAN load and count it
 * (`pdfLibLoadable: true`) yet `isEncrypted` is true. This is the oss-448 trap:
 * slicing it copies still-encrypted content streams into an unencrypted output,
 * so Doc AI receives blank pages. google-docai must decrypt before slicing.
 * Generated with the same pikepdf recipe as the object-stream fixtures but with
 * `object_stream_mode=pikepdf.ObjectStreamMode.disable`.
 */
export const ENCRYPTED_LOADABLE_PDF_20 = Buffer.from(ENC_LOADABLE20_B64, "base64");

/** The encrypted-loadable 20-page fixture after decryption (what /normalize-pdf returns): pdf-lib-sliceable, unencrypted. */
export const ENCRYPTED_LOADABLE_PDF_20_NORMALIZED = Buffer.from(
  ENC_LOADABLE20_NORMALIZED_B64,
  "base64",
);
